import { Component, OnInit, SecurityContext } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { AddOrUpdateArticleModel, IAddOrUpdateArticleModel } from '../../../../../data/model/article/AddOrUpdateArticleModel';
import { ArticleService } from '../../../../../data/service/article/article.service';
import { GResponse } from '../../../../../core/common/GResponse';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { Router } from '@angular/router';
import { Urls } from '../../../../../core/common/Urls';

@Component({
  selector: 'app-add-article',
  templateUrl: './add-article.component.html',
  styleUrls: ['./add-article.component.scss']
})
export class AddArticleComponent implements OnInit {

  shortDescription: SafeHtml;
  description: SafeHtml;
  imageUrl: any;
  addArticleForm: FormGroup;

  article: IAddOrUpdateArticleModel;

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات کوتاه...',
    translate: 'no',
    sanitize: true
  };

  editorConfig2: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات اصلی...',
    translate: 'no',
    sanitize: true
  };

  constructor(
    private articleService: ArticleService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private router: Router,
    private domSanitizer: DomSanitizer,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.addArticleForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      imageUrl: ['http://localhost:4300/assets/images/in-progress.webp', [Validators.minLength(1), Validators.maxLength(1000000)]],
      imageNamePNG: ['http://localhost:4300/assets/images/in-progress.png', [Validators.minLength(1), Validators.maxLength(1000000)]],
      shortDescriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      descriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]]
    });
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onAdd() {

    if (this.addArticleForm.valid) {

      SharedIonic.loading(this.loadingController);

      // this.shortDescription = this.domSanitizer
      //   .sanitize(SecurityContext.HTML, this.addArticleForm.value.shortDescriptionHtmlContent);

      this.shortDescription = this.addArticleForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.addArticleForm.value.descriptionHtmlContent);

      this.article =
        new AddOrUpdateArticleModel(
          null,
          this.addArticleForm.value.name,
          this.shortDescription,
          this.description,
          this.addArticleForm.value.imageUrl,
          this.addArticleForm.value.imageNamePNG
        );

      this.articleService.AddOrUpdateArticle(this.article).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            SharedIonic.successToast(this.toastController);
            this.router.navigateByUrl(Urls.HomeUrl);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
